messages.content:
Fix N+1 query pattern causing 12-second API response for /dashboard:

```javascript
// api/dashboard.js
export async function getDashboard(userId) {
  const projects = await db.query(
    'SELECT * FROM projects WHERE owner_id = $1', [userId]
  );
  for (const project of projects.rows) {
    const tasks = await db.query(
      'SELECT * FROM tasks WHERE project_id = $1', [project.id]
    );
    project.tasks = tasks.rows;
  }
  return projects.rows;
}
```

Error: 12-second response under 100 projects. pg_stat_statements shows 101 sequential scans on tasks.

### Root Cause
For each of N projects there's a separate `SELECT` on `tasks`, producing N+1 round trips. `tasks.project_id` has no index, causing full-table sequential scans.

### Patch — Batch JOIN + Missing Index
```diff
--- a/api/dashboard.js
+++ b/api/dashboard.js
@@ -1,13 +1,22 @@
 export async function getDashboard(userId) {
-  const projects = await db.query(
-    'SELECT * FROM projects WHERE owner_id = $1', [userId]
-  );
-  for (const project of projects.rows) {
-    const tasks = await db.query(
-      'SELECT * FROM tasks WHERE project_id = $1', [project.id]
-    );
-    project.tasks = tasks.rows;
-  }
-  return projects.rows;
+  // Single JOIN: 1 query instead of N+1
+  const { rows } = await db.query(`
+    SELECT
+      p.id          AS project_id,
+      p.name        AS project_name,
+      p.created_at,
+      t.id          AS task_id,
+      t.title       AS task_title,
+      t.status      AS task_status
+    FROM projects p
+    LEFT JOIN tasks t ON t.project_id = p.id
+    WHERE p.owner_id = $1
+    ORDER BY p.id, t.id
+  `, [userId]);
+
+  // Re-shape flat rows into nested structure in JS (O(n), not O(n²))
+  const projectMap = new Map();
+  for (const row of rows) {
+    if (!projectMap.has(row.project_id)) {
+      projectMap.set(row.project_id, {
+        id: row.project_id, name: row.project_name,
+        created_at: row.created_at, tasks: []
+      });
+    }
+    if (row.task_id) {
+      projectMap.get(row.project_id).tasks.push({
+        id: row.task_id, title: row.task_title, status: row.task_status
+      });
+    }
+  }
+  return [...projectMap.values()];
 }
```

### Missing Index Migration
```sql
-- migrations/0012_add_tasks_project_id_idx.sql
CREATE INDEX CONCURRENTLY idx_tasks_project_id
  ON tasks (project_id);
-- Expected: seq scan → index scan, ~200ms instead of 12s
```

### Regression Test
```javascript
import { getDashboard } from './dashboard.js';
import { db } from '../db.js';

jest.spyOn(db, 'query');

test('getDashboard fires exactly 1 SQL query', async () => {
  await getDashboard('user_1');
  expect(db.query).toHaveBeenCalledTimes(1);
});
```
